import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"Shell basics","description":"","frontmatter":{},"headers":[],"relativePath":"manual/shell-basics.md","filePath":"manual/shell-basics.md"}'),i={name:"manual/shell-basics.md"};function p(o,a,l,c,r,d){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="shell-basics" tabindex="-1">Shell basics <a class="header-anchor" href="#shell-basics" aria-label="Permalink to &quot;Shell basics&quot;">​</a></h1><p><code>ush</code> is the boot shell - a real ring-3 program (the only <code>OC_L1_APP_DECL</code> application) that fronts the whole system.</p><h2 id="the-prompt" tabindex="-1">The prompt <a class="header-anchor" href="#the-prompt" aria-label="Permalink to &quot;The prompt&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt;</span></span></code></pre></div><h2 id="running-programs" tabindex="-1">Running programs <a class="header-anchor" href="#running-programs" aria-label="Permalink to &quot;Running programs&quot;">​</a></h2><p>Type a registry program name (284 available - <code>help -a</code> lists them all). The 8 merged apps are the intended surface; the historical single commands keep working:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; hwinfo</span></span>
<span class="line"><span>ush&gt; lsblk</span></span>
<span class="line"><span>ush&gt; run hello &amp;            (the &#39;&amp;&#39; suffix runs in background)</span></span></code></pre></div><p><code>run &lt;program&gt;</code> is the explicit form - it prints the started pid and waits (or backgrounds with <code>&amp;</code>).</p><h2 id="pipes-and-redirection" tabindex="-1">Pipes and redirection <a class="header-anchor" href="#pipes-and-redirection" aria-label="Permalink to &quot;Pipes and redirection&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; cat /etc/opencube.conf | grep url</span></span>
<span class="line"><span>ush&gt; help -a &gt; registry.txt</span></span>
<span class="line"><span>ush&gt; echo hello &gt;&gt; notes.txt</span></span>
<span class="line"><span>ush&gt; wc &lt; notes.txt</span></span></code></pre></div><p>Pipes (<code>|</code>), truncating redirect (<code>&gt;</code>), appending redirect (<code>&gt;&gt;</code>) and input redirect (<code>&lt;</code>) work across registry programs.</p><h2 id="built-ins-vs-programs" tabindex="-1">Built-ins vs programs <a class="header-anchor" href="#built-ins-vs-programs" aria-label="Permalink to &quot;Built-ins vs programs&quot;">​</a></h2><p>Only process-state commands are built into ush: <code>cd</code>, <code>pwd</code>, <code>exit</code>, <code>help</code>, <code>export</code>, <code>alias</code>, <code>unalias</code>, <code>history</code>, <code>lang</code>, <code>clear</code>. Everything else - including <code>ls</code>, <code>cat</code>, <code>echo</code>, <code>write</code> - is a forked registry program. That is why <code>ls</code> appears in pipes as a real process.</p><p>The line editor: Up/Down history, Tab completion of program names, Ctrl+C cancels the line.</p><h2 id="aliases-and-environment" tabindex="-1">Aliases and environment <a class="header-anchor" href="#aliases-and-environment" aria-label="Permalink to &quot;Aliases and environment&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; alias dt disk-tool</span></span>
<span class="line"><span>ush&gt; alias</span></span>
<span class="line"><span>ush&gt; unalias dt</span></span>
<span class="line"><span>ush&gt; export EDITOR=edit</span></span></code></pre></div><h2 id="scripting" tabindex="-1">Scripting <a class="header-anchor" href="#scripting" aria-label="Permalink to &quot;Scripting&quot;">​</a></h2><p>Multi-command sequences with <code>;</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; dhcp; ping 10.0.2.2; dns example.com</span></span></code></pre></div><p>There is no file-based script interpreter in this release - a &quot;script&quot; is a pasted sequence of lines, or a program you write into the registry at build time (see the developer docs).</p><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; lang zh        (the whole UI - shell help + every wizard -</span></span>
<span class="line"><span>                     switches to Chinese live)</span></span>
<span class="line"><span>ush&gt; lang           (shows the current language)</span></span></code></pre></div><h2 id="the-mega-app-contract-recap" tabindex="-1">The mega-app contract (recap) <a class="header-anchor" href="#the-mega-app-contract-recap" aria-label="Permalink to &quot;The mega-app contract (recap)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; &lt;app&gt;                wizard (menus, single-key picks, q quits)</span></span>
<span class="line"><span>ush&gt; &lt;app&gt; direct &lt;op&gt;    explicit verbatim passthrough</span></span>
<span class="line"><span>ush&gt; &lt;app&gt; &lt;op&gt; [args]    classic dispatch (historical spelling)</span></span></code></pre></div><p>See <a href="./mega-apps.html">mega-apps</a> for the full contract and per-app walkthroughs.</p>`,25)])])}const u=e(i,[["render",p]]);export{g as __pageData,u as default};
